{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/topic-chips.json
    A centered row of topic pills: links where a topic has an address, else buttons. tone inverse: on a dark band with an icon per topic; default: outlined.
    Props (p): topics, tone. -#}
{%- set v_topics = og_def(p['topics'], none) -%}
{%- set v_tone = og_def(p['tone'], 'default') -%}
{%- set c_3 -%}
  {%- for v_topic in og_l(v_topics) %}
    {%- if og_t(og_eq(v_tone, 'inverse')) %}
      {%- set c_1 -%}
        {%- if og_t(og_get(v_topic, ['icon'])) %}
          {{ og_include('icons/lucide-icon.html.j2', {'p': {'Name': og_s(og_get(v_topic, ['icon'])), 'Size': 16}}) }}
        {%- endif %}
        {{ og_text(og_get(v_topic, ['name'])) }}
      {%- endset -%}
      {{ og_include('compose/button.html.j2', {'p': {'Href': og_url(og_s(og_get(v_topic, ['href']))), 'Variant': 'ghost', 'Size': 'sm', 'Class': 'gap-2 text-background inset-ring-background/30 hover:bg-background/10', 'Attrs': og_attrs(['data-testid', 'hero-topic'])}, 'children': c_1}) }}
    {%- else %}
      {%- set c_2 -%}
        {{ og_text(og_get(v_topic, ['name'])) }}
      {%- endset -%}
      {{ og_include('compose/button.html.j2', {'p': {'Href': og_url(og_s(og_get(v_topic, ['href']))), 'Variant': 'outline', 'Size': 'sm', 'Attrs': og_attrs(['data-testid', 'hero-topic'])}, 'children': c_2}) }}
    {%- endif %}
  {%- endfor %}
{%- endset -%}
{{ og_include('compose/group.html.j2', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'center', 'Class': 'flex-wrap', 'Attrs': og_attrs(['data-testid', 'hero-topics'])}, 'children': c_3}) }}
